package net.minecraft.world.phys;import java.util.*;public class AABB{double[]min,max;public AABB(double a,double b,double c,double d,double e,double f){min=new double[]{a,b,c};max=new double[]{d,e,f};}public AABB inflate(double d){return new AABB(min[0]-d,min[1]-d,min[2]-d,max[0]+d,max[1]+d,max[2]+d);}public boolean contains(Vec3 p){return p.x>=min[0]&&p.x<=max[0]&&p.y>=min[1]&&p.y<=max[1]&&p.z>=min[2]&&p.z<=max[2];}public Optional<Vec3>clip(Vec3 a,Vec3 b){double lo=0,hi=1;double[]p={a.x,a.y,a.z},q={b.x,b.y,b.z};for(int i=0;i<3;i++){double d=q[i]-p[i];if(Math.abs(d)<1e-9){if(p[i]<min[i]||p[i]>max[i])return Optional.empty();continue;}double x=(min[i]-p[i])/d,y=(max[i]-p[i])/d;lo=Math.max(lo,Math.min(x,y));hi=Math.min(hi,Math.max(x,y));if(lo>hi)return Optional.empty();}return Optional.of(a.add((b.x-a.x)*lo,(b.y-a.y)*lo,(b.z-a.z)*lo));}}
